Author: antonio.fabio<br>Date: Tue Feb  5 12:37:07 2008<br>New Revision: 112<p>Added:<br>   trunk/tsDyn/R/HanSeo_TVECM.R<br>   trunk/tsDyn/R/SeoTest_grid.R<br>   trunk/tsDyn/R/TVARestim.R<br>   trunk/tsDyn/R/selectSETARmat.R<br>   trunk/tsDyn/R/setarTest.R<br>   trunk/tsDyn/man/TVAR.Rd<br>   trunk/tsDyn/man/zeroyld.Rd<br>Modified:<br>   trunk/tsDyn/NAMESPACE<p>Log:<br>added Matthieu contributed code to repo<p>exported only OlsTVAR by now, added stub man page, added zeroyld dataset<p><br>Modified: trunk/tsDyn/NAMESPACE<br>==============================================================================<br>--- trunk/tsDyn/NAMESPACE	(original)<br>+++ trunk/tsDyn/NAMESPACE	Tue Feb  5 12:37:07 2008<br>@@ -9,7 +9,8 @@<br>        delta, delta.test, delta.lin, delta.lin.test,<br>        llar, llar.predict, llar.fitted, sigmoid, dsigmoid, d2sigmoid,<br>        setar, lstar, star, ncstar, availableModels, nlarDialog,<br>-       linear, isLinear, nnetTs, aar, star)<br>+       linear, isLinear, nnetTs, aar, star,<br>+	OlsTVAR)<br> S3method(extend, list)<br> S3method(isLinear, lstar)<br> S3method(toLatex, setar)<p>Added: trunk/tsDyn/R/HanSeo_TVECM.R<br>==============================================================================<br>--- (empty file)<br>+++ trunk/tsDyn/R/HanSeo_TVECM.R	Tue Feb  5 12:37:07 2008<br>@@ -0,0 +1,568 @@<br>+HanSeo_TVECM &lt;- function(dat, lag=1, gn=300, bn=300, trim=0.05, <br>boot=1000, UserSpecified_beta=NULL, cov=1, p_ests=1, intercept=TRUE, <br>UserSpecified_gamma=NULL) {<br>+##de tar_ci.m je crois<br>+# Lags in VAR beyond EC @<br>+#gn=300;			# number of gridpoints for gamma @<br>+#bn = 300;		# number of gridpoints for beta      @<br>+#trim=0.05;		# trimming percentage for threshold @<br>+#boot=1000;		% number of bootstrap replications<br>+#		        % set equal to zero to not do testing  @<br>+#coint=1;		# set to 1 to estimate cointegrating vector<br>+#			    % set to 0 to fix cointegrating vector at _cvalue @<br>+#cvalue_=1;		% cointegrating vector, if coint_=0 @<br>+#cov=1;		 	#covariance matrix estimation method<br>+#		        % set to 1 for Eicker-White<br>+#		        % set to 0 for conventional homoskedastic estimator @<br>+#p_ests_=1;		% set to 1 to print estimates, else 0 @<br>+#graph_=0;		% set to 1 to generate graph of nonlinear ECM, else 0 @<br>+#graph_rotate_=0;	% set to 1 to generate rotated graphs<br>+#		        %(useful for some print jobs, but ackward for screen <br>viewing) @<br>+<br>+### Organize Data<br>+dat&lt;-as.matrix(dat)<br>+n&lt;-nrow(dat) #n=length(dat(:,1))<br>+k&lt;-lag<br>+y&lt;-dat[(2+k):n,]-dat[(1+k):(n-1),] #y=dat(2+k:n,:)-dat(1+k:n-1,:);<br>+t&lt;-nrow(y) #t=length(y(:,1));<br>+xlag&lt;-dat[(1+k):(n-1),] # X(t-1)<br>+cvalue&lt;-UserSpecified_beta<br>+if(ncol(dat)&gt;2) {warning(&quot;Please no more than two equations&quot;)}<br>+if(is.null(colnames(dat))==TRUE){colnames(dat)&lt;-paste(&quot;Var&quot;, c(1:2), sep=&quot;&quot;)}<br>+colnames(xlag)&lt;-paste(colnames(dat), rep(-1,ncol(dat)))<br>+x&lt;-rep(1,t)		#x=ones(t,1);<br>+#j&lt;-1			#j=1;<br>+#while (j&lt;=k){<br>+ #   x&lt;-cbind(x,dat[(2+k-j):(n-j),]-dat[(1+k-j):(n-1-j),])		#x=[x,dat(2+k-j:n-j,:)-dat(1+k-j:n-1-j,:)];<br>+  #  j&lt;-j+1}<br>+#x: intercept and lags matrix<br>+<br>+##ma manière<br>+T&lt;-nrow(dat)<br>+nequ&lt;-ncol(dat)<br>+<br>+DeltaX&lt;-t(embed(diff(dat),k+1)[,-(1:nequ)])<br>+if(intercept==TRUE){<br>+DeltaX&lt;-rbind(rep(1,T-k-1), DeltaX)}<br>+x&lt;-t(DeltaX)<br>+<br>+########################<br>+### Compute Linear Model<br>+########################<br>+xx&lt;- solve(t(x)%*%x)		#xx=inv(x&#39;*x);<br>+u&lt;-y-x%*%xx%*%t(x)%*%y		#u=y-x*xx*(x&#39;*y); #Residuals for the first <br>auxiliary regression<br>+<br>+###Estimation of the cointegrating parameter<br>+if (is.null(UserSpecified_beta)==TRUE){<br>+   v&lt;-xlag-x%*%xx%*%(t(x)%*%xlag)		#Residuals for the first auxiliary <br>regression  v=xlag-x*xx*(x&#39;*xlag);<br>+    S00&lt;-t(u)%*%u				#S00 of size 2x2		#uu=u&#39;*u;<br>+    S11&lt;-t(v)%*%v				#S11 of size 2x2<br>+    m&lt;-solve(S11)%*%(t(v)%*%u)%*%solve(S00)%*%(t(u)%*%v)	#m2x2 #m=inv(v&#39;*v)*(v&#39;*u)*inv(uu)*(u&#39;*v);<br>+    ve&lt;-eigen(m)$vectors 			#eigenvectors 2x2		#[ve,va]=eig(m);<br>+    va&lt;-eigen(m)$values				#Eigenvalues 2<br>+    maa&lt;-which.max(va)				#Selectioon of the biggest eigenvalue	#   [temp,maa]=max(va);<br>+    h&lt;-ve[,maa]					#Eigenvector of the Biggest eigenvalue		#h=ve(:,maa);<br>+    b0&lt;- -h[2]/h[1]				#Eigenvalue ratio		#b0= -h(2)/h(1);<br>+		}<br>+else{ b0&lt;-UserSpecified_beta}				#b0=cvalue_;<br>+<br>+<br>+###Estimation of the parameters<br>+w0&lt;-xlag%*%c(1,-b0)				#ECT 	#w0=xlag*[1;-b0];<br>+z0&lt;-cbind(w0,x)					#ALL REGRESSORS	#z0=[w0,x];<br>+kk&lt;-length(z0[1,])				#kk=length(z0(1,:));<br>+zz0&lt;-solve(t(z0)%*%z0)			#	zz0=inv(z0&#39;*z0);<br>+zzz0&lt;-z0%*%zz0				#	zzz0=z0*zz0;<br>+beta0&lt;-t(zzz0)%*%y			#ALL Parameters	beta0=zzz0&#39;*y;<br>+colnames(beta0)&lt;-paste(&quot;Equation&quot;,colnames(dat))<br>+if(intercept==TRUE){rownames(beta0)&lt;-c(&quot;ECM&quot;,&quot;Intercept&quot;,c(paste(rep(colnames(dat),k), <br>-rep(1:k, each=nequ))))}<br>+if(intercept==FALSE) <br>{rownames(beta0)&lt;-c(&quot;ECM&quot;,c(paste(rep(colnames(dat),k), -rep(1:k, each=nequ))))}<br>+<br>+e&lt;-y-z0%*%beta0				#RESIDUALS of the VECM nx2	e=y-z0*beta0;<br>+sige&lt;-(t(e)%*%e)/t			#SIGMA	2x2 sige=e&#39;*e/t;<br>+nlike&lt;-(t/2)*log(det(sige))		#	nlike=(t/2)*log(det(sige));<br>+bic&lt;-nlike+log10(t)*4*(1+k)		#bic #=nlike+log10(t)*4*(1+k); ###BIC<br>+aic&lt;-nlike+2*4*(1+k)			#aic=nlike+2*4*(1+k);		###AIC<br>+<br>+###Standard error<br>+b_like&lt;-function(b){<br>+	z&lt;-cbind(xlag%*%c(1,-b),x)		# z=[xlag*[1;-b],x];<br>+	sigma&lt;-(t(y-z%*%(solve(t(z)%*%z)%*%t(z)%*%y))%*%(y-z%*%(solve(t(z)%*%z)%*%t(z)%*%y)))/t#sigma=((y-z*(y/z))&#39;*(y-z*(y&#39;/z&#39;)&#39;))/t;<br>+like&lt;-(t/2)*log(det(sigma))}<br>+<br>+nlike1&lt;-b_like(b0+0.001) 		#nlike1=b_like(b0+.001);<br>+nlike2&lt;-b_like(b0-0.001)			#nlike2=b_like(b0-.001);<br>+hp&lt;-(nlike1+nlike2-2*nlike)/(0.001^2)		#hp=(nlike1+nlike2-2*nlike)/(.001^2);<br>+seb&lt;-1/sqrt(hp)				#seb=1/sqrt(hp);<br>+<br>+###VARIANCe COVARIANCE<br>+if (cov==1){<br>+	lz0&lt;-ncol(z0) 			#Number of regressors (ECT, constant and lags)<br>+	xea&lt;-z0*(e[,1]%*%matrix(c(rep(1,lz0)),ncol=lz0))<br>+	xe&lt;-cbind(xea,xea)	# xe=[(z0.*(e(:,1)*ones(1,length(z0(1,:))))),(z0.*(e(:,1)*ones(1,length(z0(1,:)))))];<br>+	lr&lt;-nrow(zz0)  #=length(zz0[,1])<br>+	lc&lt;-ncol(zz0)  #=length(zz0[1,])<br>+	am0&lt;-matrix(c(rep(0, lr*lc)), ncol=lc)<br>+	m0&lt;-rbind(cbind(zz0, am0),cbind( am0, zz0))<br>+		#m0=[zz0,zeros(length(zz0(:,1)),length(zz0(1,:)));zeros(length(zz0(:,1)),length(zz0(1,:))),zz0];<br>+	v&lt;- m0%*%(t(xe)%*%xe)%*%m0		#v=m0*(xe*xe)*m0; taille attendue <br>2*para(cst +ECM+k*2<br>+	}<br>+#print(paste(&quot;dim v&quot;, dim(v)))<br>+#print(paste(&quot;dim sige&quot;, dim(sige)))<br>+#print(paste(&quot;dim zz0&quot;, dim(zz0)))<br>+if (cov==0){ v&lt;-sige%x%solve(t(z0)%*%z0)}			#v=sige.*zz0;<br>+<br>+<br>+se=sqrt(diag(v));<br>+seprint&lt;-matrix(se, nrow=2, byrow=TRUE)<br>+rownames(seprint)&lt;-paste(&quot;Equation&quot;,colnames(dat))<br>+if(intercept==TRUE){colnames(seprint)&lt;-c(&quot;ECM&quot;,&quot;Intercept&quot;,c(paste(rep(colnames(dat),k), <br>-rep(1:k, each=nequ))))}<br>+if(intercept==FALSE) <br>{colnames(seprint)&lt;-c(&quot;ECM&quot;,c(paste(rep(colnames(dat),k), -rep(1:k, each=nequ))))}<br>+<br>+######Graphical output for the linear vecm<br>+file&lt;-&quot;&quot;<br>+if(cov==1)std&lt;-&quot;Eicker-White covariance matrix estimator&quot;<br>+if(cov==0) std&lt;-&quot;standard covariance matrix estimator&quot;<br>+cat(&quot;
############################ 
###Linear VECM estimates (by <br>Johansen MLE)
############################

&quot;,  file=file, append=T)<br>+cat(&quot;Cointegrating vector&quot;, c(1, -b0))<br>+cat(&quot;
Standard error of the cointegrating value&quot;, seb)<br>+cat(&quot;
Parameters 
&quot;)<br>+print(t(beta0))<br>+cat(paste(&quot;
 Standard errors with &quot;, std), &quot;
&quot;)<br>+print(seprint)<br>+cat(&quot;
Negative LL 	&quot;, nlike)<br>+cat(&quot;
AIC 		&quot;, aic)<br>+cat(&quot;
BIC 		&quot;, bic)<br>+<br>+###Set up of the grid<br>+qa&lt;-unique(w0)<br>+q&lt;-sort(qa)<br>+gamma1&lt;-q[round(seq(from=trim, to=(gn-1)*((1-2*trim)/gn)+trim, by=((1-2*trim)/gn))*length(q))]<br>+gamma2&lt;-q[round(seq(from=1/(gn+1), by=1/(gn+1), <br>to=(gn/(gn+1)))*length(q))] #original: 1/(gn+1) moi:1/t<br>+<br>+if(is.null(UserSpecified_gamma)==FALSE) {gamma1&lt;-UserSpecified_gamma; <br>gamma2&lt;-UserSpecified_gamma; gn&lt;-1}<br>+<br>+betas&lt;-seq(from=b0 -6*seb, by=12*seb/(bn-1), to=b0 +6*seb)<br>+if (is.null(UserSpecified_beta)==FALSE) {betas&lt;-UserSpecified_beta;bn&lt;-1}<br>+################<br>+####Grid search<br>+################<br>+store&lt;-matrix(rep(0, gn*bn),ncol=bn)	#store=zeros(gn,bn)+nlike;<br>+<br>+j&lt;-1<br>+while (j&lt;=gn){<br>+   gam&lt;-gamma2[j]<br>+    bj&lt;-1<br>+    while (bj&lt;=bn){<br>+        betab&lt;-betas[bj]<br>+       w&lt;-xlag%*%c(1,-betab)	#ECT<br>+       z&lt;-cbind(w,x)		#All variables: ECT and lag<br>+       d1&lt;-ifelse(w&lt;=gam, 1,0)	#Dummy vector 		#d1=(w&lt;=gam);<br>+       n1&lt;-sum(d1)		#Number of elements of the ECT under the threshold<br>+	if(<a href="http://is.na" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://is.na&amp;source=gmail&amp;ust=1792465597147000&amp;usg=AOvVaw0XFWeqlDfxoIn6C5Kv73d-">is.na</a>(n1)==TRUE){n1&lt;-0}<br>+	if (min(n1,t-n1)/t&gt;trim) {<br>+            zj&lt;-cbind(z*c(d1), w)		#zj: Matrix with dummy on lags and <br>intercept, but not on ECT #zj=[(z.*(d1*ones(1,length(z(1,:))))),w];		<br>+	    betaj&lt;-solve(t(x)%*%x)%*%t(x)%*%zj        	    	#OLS regression zj=f(x)<br>+	    zzj&lt;-zj-x%*%betaj					# Residuals zj=f(x) #zzj=zj-x*xx*(x&#39;*zj);<br>+            # warning off;<br>+            #lastwarn(&#39; &#39;);<br>+            bz&lt;-solve(t(zzj)%*%zzj)%*%t(zzj)%*%u		#OLS regression <br>u=f(zzj) where u: Residuals for the first auxiliary regression inlinear <br>VECM # (u&#39;/zzj&#39;)&#39;;<br>+	    u_zzj&lt;-u-zzj%*%bz   				#Residuals<br>+		#[mw,idw] = lastwarn;<br>+            #lastwarn(&#39; &#39;);<br>+            #warning on;<br>+            #if (1-mw==&#39; &#39;);<br>+            #    bz=pinv(zzj&#39;*zzj)*(zzj&#39;*u);<br>+            #	end;<br>+	<br>+           store[j,bj]&lt;-(t/2)*log(det((t(u_zzj)%*%u_zzj)/t))#store(j,bj)=(t/2)*log(det((u-zzj*bz)*(u-zzj*bz)/t))<br>+	}<br>+	bj&lt;-bj+1}<br>+j&lt;-j+1}<br>+<br>+<br>+m&lt;-min(store)<br>+c&lt;-which(store==min(store), arr.ind=TRUE)[2]		#c&lt;-min(diag(store(m,:)));<br>+r&lt;-which(store==min(store), arr.ind=TRUE)[1]		#r=m(c);<br>+<br>+betaNLL&lt;-apply(store,2,FUN=min)<br>+gammaNLL&lt;-apply(store,1,FUN=min)<br>+<br>+<br>+if(is.null(UserSpecified_beta)==TRUE){<br>+layout(c(1,2))<br>+plot(gamma2,gammaNLL, type=&quot;l&quot;, xlab=&quot;Threshold parameter gamma&quot;, <br>ylab=&quot;Negative Log-Likelihood&quot;, main=&quot;Grid Search&quot;)<br>+plot(betas,betaNLL, type=&quot;l&quot;, xlab=&quot;Cointegrating parameter beta&quot;, <br>ylab=&quot;Negative Log-Likelihood&quot;, main=&quot;Grid Search&quot;)}<br>+else plot(gamma2,gammaNLL, type=&quot;l&quot;, xlab=&quot;Threshold parameter gamma&quot;, <br>ylab=&quot;Negative Log-Likelihood&quot;, main=&quot;Grid Search&quot;)<br>+<br>+gammahat&lt;-gamma2[r]<br>+b1&lt;-betas[c]<br>+<br>+nlike&lt;-store[r,c]<br>+bic&lt;-nlike+log10(t)*8*(1+k)<br>+aic&lt;-nlike+2*8*(1+k)<br>+w&lt;-xlag%*%c(1,-b1)				# w= ECT with beta estimated by the grid<br>+z&lt;-cbind(w,x)					# z= ECT and ALL regressor<br>+<br>+###################################<br>+###Subsampling estimation over/under thresh<br>+##################################<br>+z1&lt;-matrix(z[w&lt;=gammahat], ncol=ncol(z))	#observations under the threshold<br>+y1&lt;-matrix(y[w&lt;=gammahat], ncol=ncol(y))<br>+<br>+z2&lt;-matrix(z[w&gt;gammahat], ncol=ncol(z))		#observations over the trehshold<br>+y2&lt;-matrix(y[w&gt;gammahat], ncol=ncol(y))<br>+<br>+beta1&lt;-solve(t(z1)%*%z1)%*%t(z1)%*%y1<br>+beta2&lt;-solve(t(z2)%*%z2)%*%t(z2)%*%y2<br>+<br>+colnames(beta1)&lt;-paste(&quot;Equation&quot;,colnames(dat))<br>+if(intercept==TRUE){rownames(beta1)&lt;-c(&quot;ECM&quot;,&quot;Intercept&quot;,c(paste(rep(colnames(dat),k), <br>-rep(1:k, each=nequ))))}<br>+if(intercept==FALSE) <br>{rownames(beta1)&lt;-c(&quot;ECM&quot;,c(paste(rep(colnames(dat),k), -rep(1:k, each=nequ))))}<br>+<br>+colnames(beta2)&lt;-paste(&quot;Equation&quot;,colnames(dat))<br>+if(intercept==TRUE){rownames(beta2)&lt;-c(&quot;ECM&quot;,&quot;Intercept&quot;,c(paste(rep(colnames(dat),k), <br>-rep(1:k, each=nequ))))}<br>+if(intercept==FALSE) <br>{rownames(beta2)&lt;-c(&quot;ECM&quot;,c(paste(rep(colnames(dat),k), -rep(1:k, each=nequ))))}<br>+<br>+zz1&lt;-solve(t(z1)%*%z1)<br>+zz2&lt;-solve(t(z2)%*%z2)<br>+e1&lt;-y1-z1%*%beta1<br>+e2&lt;-y2-z2%*%beta2<br>+<br>+###Var Cov for the threshold model<br>+<br>+if (cov==1){<br>+	lz1&lt;-ncol(z1) 			#Number of regressors (ECT, constant and lags)<br>+	xe1a&lt;-z1*(e1[,1]%*%matrix(c(rep(1,lz1)),ncol=lz1))<br>+	xe1b&lt;-z1*(e1[,2]%*%matrix(c(rep(1,lz1)),ncol=lz1))<br>+	xe1&lt;-cbind(xe1a,xe1b)	<br>+	am1&lt;-matrix(c(rep(0, nrow(zz1)*ncol(zz1))), ncol=ncol(zz1))<br>+	m1&lt;-rbind(cbind(zz1, am1),cbind( am1, zz1))<br>+	v1&lt;- m1%*%(t(xe1)%*%xe1)%*%m1		<br>+<br>+	lz2&lt;-ncol(z2) 			#Number of regressors (ECT, constant and lags)<br>+	xe2a&lt;-z2*(e2[,1]%*%matrix(c(rep(1,lz2)),ncol=lz2))<br>+	xe2b&lt;-z2*(e2[,2]%*%matrix(c(rep(1,lz2)),ncol=lz2))<br>+	xe2&lt;-cbind(xe2a,xe2b)	<br>+	am2&lt;-matrix(c(rep(0, nrow(zz2)*ncol(zz2))), ncol=ncol(zz2))<br>+	m2&lt;-rbind(cbind(zz2,am2),cbind(am2,zz2))<br>+	v2&lt;- m2%*%(t(xe2)%*%xe2)%*%m2	<br>+} #end if cov==1<br>+<br>+else{<br>+    sig1&lt;-t(e1)%*%e1/nrow(e1)<br>+    indx&lt;-0<br>+    indy&lt;-0<br>+    for (ii in 1:nrow(sig1)){<br>+        for (jj in 1:ncol(sig1)){<br>+            if (indx==0){<br>+                tempx&lt;-zz1*sig1[ii,jj]<br>+                indx&lt;-1<br>+		} #end if indx==0<br>+            else tempx&lt;-cbind(tempx,zz1*sig1[ii,jj])<br>+	}#end fir jj<br>+	indx&lt;-0<br>+        if (indy==0){<br>+            v1&lt;-tempx<br>+            indy&lt;-1}<br>+        else v1&lt;-rbind(v1,tempx)<br>+	} #end for ii<br>+<br>+    sig2&lt;-t(e2)%*%e2/nrow(e2)<br>+    indx&lt;-0<br>+    indy&lt;-0<br>+    for (ii in 1:nrow(sig2)){<br>+        for (jj in 1:ncol(sig2)){<br>+            if (indx==0){<br>+                tempx&lt;-zz2*sig2[ii,jj]<br>+                indx&lt;-2}<br>+            else tempx&lt;-cbind(tempx,zz2*sig2[ii,jj])<br>+	} #end for jj<br>+	indx&lt;-0<br>+        if (indy==0){<br>+            v2&lt;-tempx<br>+            indy&lt;-2}<br>+        else v2&lt;-rbind(v2,tempx)<br>+	} #end for ii<br>+} #end else<br>+<br>+<br>+se1&lt;-sqrt(diag(v1))	#v1: residuals?<br>+se2&lt;-sqrt(diag(v2))<br>+rb&lt;-nrow(beta1) 		#length(beta1)<br>+bb&lt;-beta1-beta2		#Differences of the parameters<br>+<br>+se1print&lt;-matrix(se1, nrow=2, byrow=TRUE)<br>+rownames(se1print)&lt;-paste(&quot;Equation&quot;,colnames(dat))<br>+if(intercept==TRUE){colnames(se1print)&lt;-c(&quot;ECM&quot;,&quot;Intercept&quot;,c(paste(rep(colnames(dat),k), <br>-rep(1:k, each=nequ))))}<br>+if(intercept==FALSE) <br>{colnames(se1print)&lt;-c(&quot;ECM&quot;,c(paste(rep(colnames(dat),k), -rep(1:k, each=nequ))))}<br>+<br>+se2print&lt;-matrix(se2, nrow=2, byrow=TRUE)<br>+rownames(se2print)&lt;-paste(&quot;Equation&quot;,colnames(dat))<br>+if(intercept==TRUE){colnames(se2print)&lt;-c(&quot;ECM&quot;,&quot;Intercept&quot;,c(paste(rep(colnames(dat),k), <br>-rep(1:k, each=nequ))))}<br>+if(intercept==FALSE) <br>{colnames(se2print)&lt;-c(&quot;ECM&quot;,c(paste(rep(colnames(dat),k), -rep(1:k, each=nequ))))}<br>+<br>+########################<br>+###Graphical outuput<br>+########################<br>+<br>+cat(&quot;
############################ 
###Threshold VECM estimates <br>
############################

&quot;)<br>+cat(&quot;Threshold estimate 		&quot;)<br>+print(gammahat)<br>+cat(&quot;Cointegrating Vector Estimate: 	&quot;, b1)<br>+    #for i=1:length(b1)        fprintf(out,&#39;%f   &#39;,b1(i));<br>+cat(&quot;
