e para<br>+resboot&lt;-DeltaYboot-Bboot%*%Zboot					#residuals	<br>+Sigmaboot&lt;-(1/T)*resboot%*%t(resboot)					#Sigma from model<br>+<br>+Waldboot&lt;-t(matrix(alpha2boot,ncol=1)) %*%solve(solve(t(ThreshECTboot) %*%Mboot%*%ThreshECTboot)%x%Sigmaboot)%*%matrix(alpha2boot, <br>ncol=1)<br>+Waldboot<br>+}#end of the bootstrap loop<br>+<br>+Waldboots&lt;-replicate(nboot,bootstraploop(beta))<br>+PvalBoot&lt;-sum(ifelse(Waldboots&gt;supWald,1,0))/nboot<br>+CriticalValBoot&lt;-quantile(Waldboots, probs=c(0.9, 0.95, 0.975,0.99))<br>+<br>+###Graphical output<br>+plot(density(Waldboots))<br>+abline(v=c(supWald, CriticalValBoot[c(1,2)]), lty=c(1,2,3), col=c(2,3,4))<br>+legend(&quot;topright&quot;, legend=c(&quot;SupWald&quot;, &quot;Boot 10%&quot;, &quot;Boot 5%&quot;), <br>col=c(2,3,4), lty=c(1,2,3))<br>+<br>+<br>+<br>+###Output<br>+cat(&quot;
