g(thVar)) {		<br>+        if (length(thVar) &gt; Torigin) {<br>+		z &lt;- thVar[seq_len(Torigin)]<br>+		warning(&quot;The external threshold variable is not of same length as <br>the original variable&quot;)<br>+        }<br>+        else<br>+		z &lt;- thVar<br>+	z&lt;-embed(z,p+1)[,seq_len(max(thDelay))+1]		#if thDelay=2, ncol(z)=2<br>+} ###Combination (or single value indicating position) of <br>contemporaneous variables<br>+else {<br>+	if (length(mTh) &gt; k)<br>+		stop(&quot;length of &#39;mTh&#39; should be equal to the number of variables, or <br>just one&quot;)<br>+	if(length(mTh)==1) {<br>+		if(mTh&gt;p)<br>+			stop(&quot;mTh too big, should be smaller or equal to the number of variables&quot;)<br>+		combin &lt;- matrix(0,ncol=1, nrow=k)<br>+		combin[mTh,]&lt;-1<br>+	}<br>+	zcombin &lt;- y %*% combin<br>+	z &lt;- embed(zcombin,p+1)[,seq_len(max(thDelay))+1]		#if thDelay=2, ncol(z)=2<br>+}<br>+<br>+trans&lt;-as.matrix(z)<br>+<br>+###############################<br>+###Grid for transition variable<br>+###############################<br>+<br>+allgammas &lt;- sort(unique(trans[,1]))<br>+nga &lt;- length(allgammas)<br>+ninter &lt;- round(trim*nga)<br>+gammas &lt;- allgammas[(trim*nga):((1-trim)*nga)]<br>+if(!missing(ngrid)){<br>+	gammas &lt;- allgammas[seq(from=ceiling(trim*nga), <br>to=floor((1-trim)*nga), length.out=ngrid)]<br>+}<br>+if(!missing(gamma))<br>+	gammas&lt;-gamma<br>+Y&lt;-t(Y)					#dim k x t<br>+<br>+aroundGrid &lt;- function(around,allgammas,ngrid,trim){<br>+	ng &lt;- length(allgammas)<br>+	wh.around &lt;- which(round(allgammas,5)==round(around,5))<br>+	if(length(wh.around)==0)<br>+		stop(&quot;Sorry, the value you gave for the around argument did not match&quot;)<br>+	ar &lt;- c((wh.around-round(ngrid/2)): (wh.around+round(ngrid/2)))		<br>#Values around the point<br>+	ar2 &lt;- ar[ar&gt;=round(trim*ng)&amp;ar&lt;=round((1-trim)*ng)]			#Bounding with trim<br>+	gammas &lt;- allgammas[ar2]<br>+	return(gammas)<br>+}#end if missing around<br>+<br>+if(!missing(around)){<br>+	if(length(around)==1)<br>+		gammas &lt;- aroundGrid(around, allgammas,ngrid,trim)<br>+	if(length(around)==2) {<br>+		gammas &lt;- aroundGrid(around[1], allgammas,ngrid,trim)<br>+		gamas2 &lt;- aroundGrid(around[2], allgammas,ngrid,trim)<br>+	}<br>+}<br>+<br>+######################<br>+###One threshold model					<br>+######################<br>+<br>+loop1 &lt;- function(gam1, d){<br>+	##Threshold dummies<br>+	regimedown &lt;- ifelse(trans[,d]&lt;gam1, 1,0) * Z<br>+	##SSR<br>+	Z1 &lt;- t(cbind(regimedown, Z))		# dim k(p+1) x t<br>+	B1 &lt;- tcrossprod(Y,Z1) %*% solve(tcrossprod(Z1))<br>+	crossprod(c( Y - B1 %*% Z1))<br>+} #end of the function<br>+<br>+onesearch &lt;- function(thDelay,gammas){<br>+	grid1 &lt;- expand.grid(thDelay,gammas)				#grid with delay and gammas<br>+	store &lt;- mapply(loop1,d=grid1[,1],gam1=grid1[,2])			#search for <br>values of grid<br>+	posBestThresh &lt;- which(store==min(store, na.rm=TRUE), arr.ind=TRUE)[1]<br>+<br>+	if(plot){<br>+		result1 &lt;- cbind(grid1,store)<br>+		col &lt;- rep(thDelay,length.out=nrow(result1))<br>+		plot(result1[,2], result1[,3], col=col,xlab=&quot;Treshold <br>Value&quot;,ylab=&quot;SSR&quot;, main=&quot;Results of the grid search&quot;)<br>+		legend(&quot;topleft&quot;, pch=1, legend=paste(&quot;Threshold Delay&quot;, thDelay), col=thDelay)<br>+	}<br>+	cat(&quot;Best unique threshold&quot;, grid1[posBestThresh,2],&quot;
