br>+if(length(gammas)-wh.thresh&gt;ninter){<br>+	gammaPlus &lt;- gammas[(wh.thresh+ninter/2):length(gammas)]<br>+	storePlus &lt;- mapply(loop2,gam1=bestThresh,gam2=gammaPlus, d=bestDelay)<br>+}<br>+else<br>+	storePlus &lt;- NA<br>+<br>+#results<br>+store2 &lt;- c(storeMinus, storePlus)<br>+<br>+positionSecond &lt;- which(store2==min(store2, na.rm=TRUE), arr.ind=TRUE)<br>+if(positionSecond&lt;=length(storeMinus))<br>+	secondBestThresh&lt;-gammaMinus[positionSecond]<br>+else<br>+	secondBestThresh&lt;-gammaPlus[positionSecond]<br>+<br>+cat(&quot;Second best (conditionnal on the first one)&quot;, <br>c(bestThresh,secondBestThresh), &quot;	 SSR&quot;, min(store2, na.rm=TRUE), &quot;
&quot;)<br>+<br>+###Iterative step<br>+smallThresh &lt;- min(bestThresh,secondBestThresh)<br>+gammasDown &lt;- aroundGrid(around=smallThresh,allgammas,ngrid=30, trim=trim)<br>+<br>+bigThresh &lt;- max(bestThresh,secondBestThresh)<br>+gammasUp &lt;- aroundGrid(around=bigThresh,allgammas,ngrid=30, trim=trim)<br>+<br>+storeIter &lt;- matrix(NA,ncol=length(gammasUp), nrow=length(gammasDown))<br>+<br>+#Grid search<br>+for(i in seq_len(length(gammasDown))){<br>+	gam1 &lt;- gammasDown[i]<br>+	for(j in 1: length(gammasUp)){<br>+		gam2 &lt;- gammasUp[j]<br>+		storeIter[i,j] &lt;- loop2(gam1=gam1, gam2=gam2, d=bestDelay)<br>+	}<br>+}<br>+<br>+#Finding the best result<br>+positionIter &lt;- which(storeIter==min(storeIter, na.rm=TRUE), arr.ind=TRUE)<br>+rIter &lt;- positionIter[1]<br>+cIter &lt;- positionIter[2]<br>+<br>+gamma1Iter &lt;- gammasDown[rIter]<br>+gamma2Iter &lt;- gammasUp[cIter]<br>+<br>+bestThresh &lt;- c(gamma1Iter, gamma2Iter)<br>+<br>+cat(&quot;
Second step best thresholds&quot;, bestThresh, &quot;			 SSR&quot;, <br>min(storeIter, na.rm=TRUE), &quot;
