&quot;)<br>+}<br>+if(length(thDelay)&gt;1) stop(&quot;length of thDelay should not be bigger <br>than 1. The whole search is made only upon the thresholds with given delay&quot;)<br>+<br>+store3 &lt;- matrix(NA,ncol=length(gammas2), nrow=length(gammas))<br>+<br>+###Loop<br>+for(i in seq_len(length(gammas))){<br>+	gam1 &lt;- gammas[i]<br>+	for (j in seq_len(length(gammas))){<br>+		gam2 &lt;- gammas2[j]<br>+		store3[i,j] &lt;- loop2(gam1, gam2, d=bestDelay)<br>+	}<br>+}<br>+<br>+position &lt;- which(store3==min(store3, na.rm=TRUE), arr.ind=TRUE)<br>+print(position)<br>+r &lt;- position[1]<br>+c &lt;- position[2]<br>+<br>+gamma1 &lt;- gammas[r]<br>+gamma2 &lt;- gammas2[c]<br>+bestThresh &lt;- c(gamma1, gamma2)<br>+<br>+}#end n<br>+<br>+#############<br>+###Best Model<br>+#############<br>+if(nthresh==1){<br>+	dummydown &lt;- ifelse(trans[,bestDelay]&lt;bestThresh, 1, 0)<br>+	ndown &lt;- mean(dummydown)<br>+	regimedown &lt;- dummydown*Z<br>+	Zbest &lt;- t(cbind(regimedown,Z))		# dim k(p+1) x t<br>+}<br>+if(nthresh==2|nthresh==3){<br>+	dummydown &lt;- ifelse(trans[,bestDelay]&lt;bestThresh[1], 1,0)<br>+	ndown &lt;- mean(dummydown)<br>+	regimedown &lt;- dummydown*Z<br>+	dummyup &lt;- ifelse(trans[,bestDelay]&gt;=bestThresh[2], 1,0)<br>+	nup &lt;- mean(dummyup)<br>+	regimeup &lt;- dummyup*Z<br>+	Zbest &lt;- t(cbind(regimedown,Z, regimeup))	# dim k(p+1) x t<br>+}<br>+<br>+Bbest &lt;- Y %*% t(Zbest) %*% solve(Zbest %*% t(Zbest))<br>+rownames(Bbest) &lt;- paste(&quot;Equation&quot;, colnames(data))<br>+Bcolnames &lt;- c(&quot;Trend&quot;, c(paste(rep(colnames(data),p),&quot;t&quot;, -rep(1:p, each=k))))<br>+if(!trend)<br>+	Bnames&lt;-c(c(paste(rep(colnames(data),p), &quot;t&quot;,-rep(1:p, each=k))))<br>+resbest &lt;- Y - Bbest %*% Zbest<br>+SSRbest &lt;- crossprod(c(resbest))<br>+<br>+if(nthresh==1)<br>+	colnames(Bbest) &lt;- rep(Bcolnames,2)<br>+else<br>+	colnames(Bbest)&lt;-rep(Bcolnames,3)<br>+<br>+if(nthresh==1){<br>+	Bdown &lt;- Bbest[,c(1:npar)]<br>+	Bup &lt;- Bbest[,-c(1:npar)]<br>+	Blist &lt;- list(Bdown=Bdown, Bup=Bup)<br>+	nobs &lt;- list(ndown=ndown, nup=1-ndown)<br>+} else {<br>+	Bdown &lt;- Bbest[,c(1:npar)]<br>+	Bmiddle &lt;- Bbest[,c(1:npar)+npar]<br>+	Bup &lt;- Bbest[,c(1:npar)+2*npar]<br>+	colnames(Bmiddle) &lt;- Bcolnames<br>+	Blist &lt;- list(Bdown=Bdown, Bmiddle=Bmiddle,Bup=Bup)<br>+	nobs &lt;- list(ndown=ndown, nmiddle=1-nup-ndown,nup=nup)<br>+}<br>+<br>+list(Thresh=bestThresh, Parameters=Blist, SSR=SSRbest, nobs_regimes=nobs)<br>+}	#end of the whole function<br>+<br>+if(FALSE) { #usage example<br>+###Hansen Seo data<br>+zeroyld &lt;- read.table(file=&quot;/media/sda5/Mes <br>documents/Ordi/MatLab/commandes/Commandes Hansen Seo/zeroyld.txt&quot;, <br>header=FALSE, sep=&#39;&#39;)<br>+#Windows<br>+#zeroyld &lt;- read.table(file=&quot;E:/Mes <br>documents/Ordi/MatLab/commandes/Commandes Hansen Seo/zeroyld.txt&quot;, <br>header=FALSE, sep=&#39;&#39;)<br>+#data&lt;-dat[,c(30,13)];<br>+<br>+data&lt;-zeroyld[,c(36,19)]<br>+colnames(data)&lt;-c(&quot;short&quot;, &quot;long&quot;)<br>+<br>+OlsTVAR(data, lag=2, nthresh=3, thDelay=1,trim=0.1, mTh=1,ngrid, plot=FALSE)<br>+#lag2, 2 thresh, trim00.05: 561.46<br>+}<p>Added: trunk/tsDyn/R/selectSETARmat.R<br>==============================================================================<br>--- (empty file)<br>+++ trunk/tsDyn/R/selectSETARmat.R	Tue Feb  5 12:37:07 2008<br>@@ -0,0 +1,133 @@<br>+selectSETARmat&lt;- function (x, m, d = 1, steps = d, thSteps = 7, mL = <br>1:m, mH = 1:m,<br>+    th = quantile(x, prob = seq(0.15, 0.85, length = thSteps)),<br>+    thDelay = seq_len(m)-1, criterion = <br>c(&quot;pooled-AIC&quot;, &quot;AIC&quot;, &quot;SSR_OLS&quot;), trim=0.15, ngrid=&quot;ALL&quot;, around, <br>plot=TRUE) {<br>+<br>+if (max(thDelay) &gt;= m)<br>+	stop(paste(&quot;thDelay too high: should be &lt; m (=&quot;, m, &quot;)&quot;))<br>+str &lt;- nlar.struct(x, m, d, steps)<br>+xx &lt;- getXX(str)<br>+yy &lt;- getYY(str)<br>+<br>+### Grid for threshold values<br>+allgammas &lt;- sort(unique(x[- seq_len(m)]))<br>+ng &lt;- length(allgammas)<br>+if(ngrid==&quot;ALL&quot;){<br>+	gammas &lt;- allgammas[round(trim*ng):round((1-trim)*ng)]<br>+} else {<br>+	if(ngrid&gt;ng)<br>+		warning(&quot;There a not so many threshold values. Only &quot;, ng, &quot;values <br>will be computed&quot;)<br>+ 	gammas &lt;- allgammas[seq(from=trim, to=1-trim, length.out=ngrid)*ng]<br>+}<br>+<br>+if(!missing(around)){<br>+	if(missing(ngrid)) {<br>+		ngrid &lt;- 20;<br>+		cat(&quot;Searching for 20 values around
&quot;)<br>+	}<br>+	wh.around &lt;- which( round(allgammas,5) == round(around,5) )<br>+	if(length(wh.around)==0)<br>+		stop(&quot;Sorry, the value you gave for the around argument did not match&quot;)<br>+	ar &lt;- c((wh.around-round(ngrid/2)) : (wh.around+round(ngrid/2)))	<br>#Values around the point<br>+	gammas &lt;- allgammas[ar[ar&gt;=round(trim*ng)&amp;ar&lt;=round((1-trim)*ng)]]	#grid<br>+}<br>+<br>+th &lt;- gammas<br>+<br>+###Function pooled AIC<br>+pooledAIC &lt;- function(parms) {	<br>+	thDelayVal &lt;- parms[1] + 1<br>+	mLVal &lt;- parms[2]<br>+	mHVal &lt;- parms[3]<br>+	m &lt;- max(thDelayVal, mLVal, mHVal)<br>+	lags &lt;- c( (seq_len(m)-1) * (-d), steps)<br>+	xxyy &lt;- embedd(x, lags = lags)<br>+	z &lt;- xxyy[, thDelayVal]<br>+	isLow &lt;- (z &lt;= parms[4])<br>+	if ((sum(isLow) &lt; mLVal) | (sum(!isLow) &lt; mHVal))<br>+	    return(NA)<br>+	xx &lt;- xxyy[isLow, seq_len(mLVal)]<br>+	y &lt;- xxyy[isLow, m + 1]<br>+	AIC1 &lt;- AIC(lm(y ~ xx))<br>+	xx &lt;- xxyy[!isLow, seq_len(mHVal)]<br>+	y &lt;- xxyy[!isLow, m + 1]<br>+	AIC2 &lt;- AIC(lm(y ~ xx))<br>+	return(AIC1 + AIC2)<br>+}<br>+<br>+###Function for usual AIC<br>+parsToModel &lt;- function(parms) {<br>+	thDelayVal &lt;- parms[1]<br>+	mLVal &lt;- parms[2]<br>+	mHVal &lt;- parms[3]<br>+	thVal &lt;- parms[4]<br>+	m &lt;- max(thDelayVal + 1, mLVal, mHVal)<br>+	return(setar(x, m = m, d = d, steps = steps, mL = mLVal,<br>+		mH = mHVal, th = thVal, thDelay=thDelayVal))<br>+}<br>+<br>+### SSR function<br>+SSRestim &lt;- function(parameters) {<br>+	Delay &lt;- parameters[1]<br>+	gammai &lt;- parameters[2]<br>+        isL &lt;- ifelse(xx[, Delay + 1]&lt; gammai,1,0)	### isL: dummy variable<br>+        xxL &lt;- cbind(1, xx[, mL]) * isL		### Lower matrix<br>+        xxH &lt;- cbind(1, xx[, mH]) * (1 - isL)	### Upper matrix<br>+	xxB &lt;- cbind(xxL, xxH)<br>+	crossprod(yy - xxB %*% chol2inv( chol( crossprod(xxB) ) ) %*% <br>crossprod(xxB, yy) )<br>+}<br>+<br>+###Grid for computation<br>+    x &lt;- str$x<br>+    IDS &lt;- as.matrix(expand.grid(thDelay,  mL, mH, th))			###Matrix of <br>all combinations<br>+	colnames(IDS)&lt;-c(&quot;thDelay&quot;, &quot;mL&quot;, &quot;mH&quot;, &quot;th&quot;)<br>+    IDS2 &lt;- as.matrix(expand.grid(thDelay, th))<br>+	colnames(IDS2)&lt;-c(&quot;thDelay&quot;, &quot;th&quot;)<br>+###Computation<br>+criterion &lt;- match.arg(criterion)<br>+IDS &lt;- switch(criterion, AIC = IDS, &quot;pooled-AIC&quot; = IDS, &quot;SSR_OLS&quot; =  <br>IDS2)	###Selection of the grid<br>+if (criterion == &quot;pooled-AIC&quot;) {<br>+    computedCriterion &lt;- apply(IDS, 1, pooledAIC)<br>+} else if(criterion==&quot;AIC&quot;){<br>+    critFun &lt;- switch(criterion, AIC = AIC)<br>+    computedCriterion &lt;- apply(IDS, 1, function(x) critFun(parsToModel(x)))<br>+} else if(criterion==&quot;SSR_OLS&quot;){<br>+    computedCriterion &lt;- apply(IDS, 1, SSRestim )<br>+}<br>+<br>+###Results<br>+res &lt;- cbind(IDS, computedCriterion)<br>+<br>+###Graphical outuput<br>+if(plot==TRUE){<br>+	allcol &lt;- seq_len(max(thDelay+1)*max(mL)*max(mH))<br>+	col &lt;- switch(criterion, <br>AIC=allcol, &quot;pooled-AIC&quot;=allcol,&quot;SSR_OLS&quot;=(thDelay+1) )<br>+	big &lt;- apply(expand.grid(thDelay,mL, mH),1,function(a) paste(&quot;Th:&quot;, <br>a[1],&quot;mL:&quot;, a[2], &quot;mH:&quot;, a[3]))<br>+	legend &lt;- <br>switch(criterion, &quot;AIC&quot;=big, &quot;pooled-AIC&quot;=big, &quot;SSR_OLS&quot;=paste(&quot;Threshold <br>Delay&quot;, thDelay))<br>+<br>+	plot(res[,&quot;th&quot;], res[,&quot;computedCriterion&quot;], col=col, xlab=&quot;Treshold <br>Value&quot;,ylab=criterion, main=&quot;Results of the grid search&quot;)<br>+	legend(&quot;topleft&quot;, pch=1, legend=legend, col=col, bg=0)<br>+}<br>+### Results<br>+colnames(res) &lt;- c(colnames(IDS), criterion)<br>+idSel &lt;- sort(computedCriterion, index = TRUE)$ix<br>+idSel &lt;- idSel[seq_len(min(10, length(idSel)))]<br>+res &lt;- data.frame(res[idSel, ], row.names = NULL)<br>+<br>+return(res)<br>+}<br>+<br>+if(FALSE) { #usage example<br>+library(tsDyn)<br>+environment(selectSETARmat)&lt;-environment(selectNNET)<br>+<br>+<br>+#Transformation like in Hansen 1999<br>+sun&lt;-(sqrt(sunspot.year+1)-1)*2		<br>+<br>+###Full grid search with OLS<br>+selectSETARmat(sun, m=2, criterion=&quot;SSR_OLS&quot;, d=1, thDelay=0:1)<br>+<br>+###restricted search with AIC or AIC pooled around the max selected by OLS<br>+selectSETARmat(sun, m=2, criterion=&quot;AIC&quot;, d=1, thDelay=0:1, around=7.444575)<br>+}<br>+<p>Added: trunk/tsDyn/R/setarTest.R<br>==============================================================================<br>--- (empty file)<br>+++ trunk/tsDyn/R/setarTest.R	Tue Feb  5 12:37:07 2008<br>@@ -0,0 +1,124 @@<br>+setarTest &lt;- function (x, m, d = 1, steps = d, series, thDelay = 0:1, <br>mL, mH,<br>+    mTh, thVar, th, nboot=10, plot=FALSE) {<br>+    if (missing(m)) m &lt;- max(mL, mH, max(thDelay) + 1)<br>+    if (missing(series))  series &lt;- deparse(substitute(x))<br>+    str &lt;- nlar.struct(x = x, m = m, d = d, steps = steps, series = series)<br>+    xx &lt;- str$xx<br>+    yy &lt;- str$yy<br>+    externThVar &lt;- FALSE<br>+<br>+###Linear model<br>+xxlin&lt;-cbind(1,xx)<br>+linear &lt;- lm.fit(xxlin, yy)<br>+SSR&lt;-crossprod(linear$residuals)<br>+<br>+<br>+###Threshold transition variable<br>+    if (missing(mL)) { mL &lt;- m    }<br>+    if (missing(mH)) { mH &lt;- m    }<br>+    if (!missing(thDelay)) {<br>+      if (max(thDelay) &gt;= m)             stop(paste(&quot;thDelay too high: <br>should be &lt; m (=&quot;,  m, &quot;)&quot;))<br>+        z &lt;- xx[, thDelay + 1]<br>+    }<br>+    else if (!missing(mTh)) { stop(&quot;Currenly not implemented&quot;)<br>+	    if (length(mTh) != m) stop(&quot;length of &#39;mTh&#39; should be equal to &#39;m&#39;&quot;)<br>+        z &lt;- xx %*% mTh<br>+        dim(z) &lt;- NULL<br>+    }<br>+    else if (!missing(thVar)) {<br>+        if (length(thVar) &gt; nrow(x)) {thVar &lt;- thVar[seq_len(nrow(x))]}<br>+	if (length(thVar) &lt; nrow(x)) {stop(&quot;The threshold variable should not <br>be smaller than the serie&quot;) }<br>+	z&lt;-nlar.struct(x = thVar, m = m, d = d, steps = steps, series = <br>deparse(substitute(z)))[, thDelay + 1]<br>+    }<br>+    else {z &lt;- xx[, thDelay]<br>+    }<br>+<br>+### Threshold model<br>+ng&lt;-nrow(xx)<br>+<br>+SSRestim&lt;-function(parameters) {<br>+	thDelay&lt;-parameters[1]<br>+	gammai&lt;-parameters[2]<br>+        isL &lt;- ifelse(z[, thDelay + 1]&lt; gammai,1,0)	### isL: dummy<br>+        xxL &lt;- cbind(1, xx[, seq_len(mL)]) * isL	### Lower matrix<br>+        xxH &lt;- cbind(1, xx[, seq_len(mH)]) * (1 - isL)	### Upper matrix<br>+	crossprod(lm.fit(cbind(xxL, xxH), yy)$residuals)### SSR of thresh model<br>+        }<br>+<br>+gammas&lt;-apply(xx[-c(1:m),],2, sort)[round(trim*ng):round((1-trim)*ng),]<br>+IDS&lt;-as.matrix(expand.grid(thDelay, gammas))<br>+result &lt;- apply(IDS, 1, SSRestim )<br>+SSRthresh&lt;-min(result)<br>+<br>+###F test<br>+Ftest&lt;-as.numeric(nrow(xx)*(SSR-SSRthresh)/SSRthresh)<br>+<br>+###Bootstrap for the F test<br>+#initial values<br>+xboot&lt;-vector(&quot;numeric&quot;, length=length(x))		#Delta Y term<br>+xboot[1:m]&lt;-x[1:m]			<br>+resi&lt;-c(rep(0,m),linear$residuals)<br>+ng&lt;-nrow(xx)<br>+<br>+#loop<br>+bootstraploop&lt;-function(B){<br>+<br>+#reconstruction of the serie<br>+resi&lt;-sample(resi, replace=TRUE)			#residual sampling, comment this <br>line to verify the function<br>+for(i in (m+1):length(x)){<br>+	xboot[i]&lt;-sum(B[1],B[-1]*xboot[i-c(1:m)],resi[i])<br>+	}<br>+str &lt;- nlar.struct(x = xboot, m = m, d = d, steps = steps)<br>+<br>+#SSR for linear model<br>+xxb &lt;- cbind(1,str$xx)<br>+yyb &lt;- str$yy<br>+SSRb&lt;-crossprod(yyb-xxb%*%chol2inv(chol(crossprod(xxb)))%*%crossprod(xxb,yyb)) <br>#SSR<br>+<br>+#SSR for threshold model<br>+SSRestim&lt;-function(parameters) {<br>+	thDelay&lt;-parameters[1]<br>+	gammai&lt;-parameters[2]<br>+        isL &lt;- ifelse(z[, thDelay + 1]&lt; gammai,1,0)	### isL: dummy<br>+        xxbT &lt;- cbind(xxb*isL,xxb * (1 - isL))		### Upper matrix<br>+	<br>#crossprod(yyb-xxbT%*%chol2inv(chol(crossprod(xxbT)))%*%crossprod(xxbT,yyb)) <br>### SSR of thresh model<br>+        crossprod(qr.resid(qr(xxbT),yyb))<br>+	#crossprod(lm.fit(xxbT,yyb)$residuals)<br>+}<br>+<br>+gammas&lt;-sort(unique(xboot))[round(trim*ng):round((1-trim)*ng)]	<br>#Treshold values<br>+IDSb&lt;-as.matrix(expand.grid(thDelay, gammas))			#Combinations of <br>thresold and delays<br>+SSRthreshb&lt;-min(apply(IDSb, 1, SSRestim ))			#Minimal SSR<br>+<br>+#Test statistic<br>+ng*(SSRb-SSRthreshb)/SSRthreshb<br>+}#end of bootstraploop<br>+<br>+Ftestboot&lt;&lt;-replicate(n=nboot,bootstraploop(linear$coefficients))<br>+Ftest&lt;&lt;-Ftest<br>+PvalBoot&lt;-sum(ifelse(Ftestboot&gt;Ftest,1,0))/nboot<br>+CriticalValBoot&lt;-quantile(Ftestboot, probs=c(0.9, 0.95, 0.975,0.99))<br>+<br>+<br>+###Grahical output<br>+if(plot==TRUE){<br>+	plot(density(Ftestboot), xlab=&quot;SSR value&quot;, ylim=c(0,0.10), xlim=c(-10,80))<br>+	abline(v=Ftest, lty=2, col=2)<br>+	curve(dchisq(x, df=1+m, ncp=0), from=0, n=100, add=TRUE, col=3)<br>+	legend(&quot;topright&quot;, legend=c(&quot;Asymptotic Chi 2&quot;, &quot;Bootstrap&quot;, &quot;Test <br>value&quot;), col=c(2,1,3), lty=c(1,1,1))<br>+}<br>+<br>+<br>+#nlar=extend(nlar(str, coef = res$coef, fit = res$fitted.values, res = <br>res$residuals, k = res$k,<br>+#list( model.specific = res),&quot;setar&quot;)<br>+return(list(linear.SSR=SSR, thresh.SSR=SSRthresh, test.val=Ftest, <br>Pvalueboot=PvalBoot, CriticalValBoot=CriticalValBoot))<br>+}#End of thw whole function<br>+<br>+if(FALSE){ #usage example<br>+environment(setarTest)&lt;-environment(setar)<br>+#Transformation like in Hansen 1999<br>+sun&lt;-(sqrt(sunspot.year+1)-1)*2<br>+<br>+setarTest(sun, m=11, thDelay=0:1, nboot=2, plot=TRUE)<br>+}<br>+<p>Added: trunk/tsDyn/man/TVAR.Rd<br>==============================================================================<br>--- (empty file)<br>+++ trunk/tsDyn/man/TVAR.Rd	Tue Feb  5 12:37:07 2008<br>@@ -0,0 +1,51 @@<br>+
ame{TVAR}<br>+\alias{TVAR}<br>+\alias{OlsTVAR}<br>+	itle{Multivariate Treshold Autoregressive model}<br>+\description{<br>+Estimate a multivariate Threshold VAR<br>+}<br>+\usage{<br>+OlsTVAR(data, lag, type=c(&quot;level&quot;, &quot;difference&quot;), trend=TRUE, <br>nthresh=1, trim=0.1, ngrid, gamma=NULL, thDelay=1, mTh=1, thVar, <br>around, plot=TRUE)<br>+}<br>+\value{<br>+Fitted model data<br>+}<br>+\arguments{<br>+\item{data}{ time series }<br>+\item{lag}{TODO}<br>+\item{type}{TODO}<br>+\item{trend}{TODO}<br>+\item{thDelay}{&#39;time delay&#39; for the threshold variable (as multiple of <br>embedding time delay d)}<br>+\item{thVar}{external threshold variable}<br>+\item{mTh}{combinations of simulatneous variables for the trehhold. <br>either a single value (indicating which variable to take) or a combination}<br>+\item{gamma}{prespecified threshold values}<br>+\item{nthresh}{number of threshold (see details)}<br>+\item{ngrid}{number of elements of the grid, especially for \code{nthresh=3}}<br>+\item{around}{especially for \code{nthresh=3}. The grid search is made <br>around the values given (with length \var{ngrid})}<br>+\item{Trim}{trimming parameter indicating the minimal percentage of <br>observations in each regime}<br>+}<br>+\details{<br>+nthresh=1: estimation upon a grid of thresholds and possible delays<br>+<br>+nthresh=2: conditional estimation: conditional on the threshold found <br>in model where nthresh=1, the second thresghold is searced. When both <br>are foun, a second grid search is made with 30 values around each threshold<br>+<br>+nthresh=3: DOES NOT estimate a 3 regimes, but a 2 regimes with a whole <br>grid over the parameters, is there rather to check the consistency of <br>the method nthresh=2<br>+}<br>+\seealso{<br>+TODO<br>+}<br>+\author{Matthieu Stigler}<br>+\examples{<br>+data(zeroyld)<br>+data &lt;- zeroyld[,c(36,19)]<br>+colnames(data) &lt;- c(&quot;short&quot;, &quot;long&quot;)<br>+<br>+OlsTVAR(data, lag=2, nthresh=3, thDelay=1,trim=0.1, mTh=1, ngrid, plot=FALSE)<br>+#lag2, 2 thresh, trim00.05: 561.46<br>+}<br>+\keyword{ ts }<br>+eferences{<br>+TODO<br>+}<br>+<p>Added: trunk/tsDyn/man/zeroyld.Rd<br>==============================================================================<br>--- (empty file)<br>+++ trunk/tsDyn/man/zeroyld.Rd	Tue Feb  5 12:37:07 2008<br>@@ -0,0 +1,8 @@<br>+
